import fs from 'fs-extra';
import os from 'node:os';
import path from 'node:path';
import { planLegacyHookDedupe, type HookWrapperLike, type PreservedClassification } from './legacy-hook-dedupe.js';
import { LEGACY_XTRM_SKILLS_ENTRIES } from './pi-runtime.js';

/** Pi settings array fields that can carry a global/project duplicate. */
const PI_ARRAY_FIELDS = ['packages', 'extensions', 'skills'] as const;
export type PiArrayField = typeof PI_ARRAY_FIELDS[number];

// Read-only audit of the settings.json files xt writes into (xtrm-kdwvu).
//
// Reports six finding classes across the home scope (~/.claude/settings.json,
// ~/.pi/agent/settings.json, ~/.pi/settings.json) and the project scope
// (<root>/.claude/settings.json, <root>/.pi/settings.json).
//
// Ownership rule, inherited from docs/architecture/repair-transaction.md: a
// finding is only ever raised on evidence — a path that does not exist, a key
// on an explicit retired list, a registration proven redundant by
// legacy-hook-dedupe. Ownership is never inferred from absence, so foreign and
// user-authored entries are reported as `preserved`, never as removable.
//
// `auditSettings` never writes. `applySettingsFixes` (xtrm-tzzud) is the only
// mutating entry point, it acts exclusively on findings the audit marked
// `fixable`, and it backs each file up before touching it. A finding is
// fixable only when the removal is xt-owned AND deterministic: a project entry
// the global settings are proven to declare, a retired key xt itself wrote, or
// a dangling pointer on xt's own legacy-pointer list. Hook findings are never
// fixable here — they belong to `xt update --apply` and to
// scripts/dedupe-legacy-hooks.mjs, which own the coverage+hash proof.

export type FindingKind =
    | 'dead-hook-command'
    | 'duplicate-registration'
    | 'duplicate-of-global'
    | 'legacy-path'
    | 'legacy-beads-hook'
    | 'dangling-reference'
    | 'orphaned-key';

export type Scope = 'home' | 'project';

/** A deterministic, xt-owned removal `--fix` can perform for a finding. */
export type FixAction =
    | { op: 'remove-array-entry'; field: PiArrayField; entry: string }
    | { op: 'delete-key'; key: string };

export interface SettingsFinding {
    kind: FindingKind;
    scope: Scope;
    file: string;
    /** Short human label, e.g. the event or key the finding sits on. */
    subject: string;
    evidence: string;
    remediation: string;
    /** Present only when `--fix` can resolve this finding. */
    fix?: FixAction;
}

export interface AppliedFix {
    file: string;
    subject: string;
    /** Absolute path of the pre-write copy. */
    backup: string;
}

export interface PreservedEntry {
    scope: Scope;
    file: string;
    subject: string;
    classification: PreservedClassification;
    reason: string;
}

export interface AuditFailure {
    file: string;
    error: string;
}

export interface SettingsAuditOutcome {
    schema: 'ReconciliationOutcome/1';
    generatedAt: string;
    /** True only after `applySettingsFixes` wrote at least one file. */
    changed: boolean;
    planned: SettingsFinding[];
    /** Empty from `auditSettings`; filled by `applySettingsFixes({ apply: true })`. */
    applied: AppliedFix[];
    preserved: PreservedEntry[];
    failed: AuditFailure[];
    scanned: string[];
}

export interface AuditOptions {
    projectRoot?: string;
    scope: 'home' | 'project' | 'all';
    scanAllRepos?: boolean;
    home?: string;
}

// Paths and identifiers the pre-global-migration installer used. A hit means
// the file still carries plugin-era or per-repo residue.
const LEGACY_PATTERNS: Array<{ re: RegExp; label: string }> = [
    { re: /skills\/active\/(?:claude|pi)\b/, label: 'per-runtime active skills view (now flat .xtrm/skills/active)' },
    { re: /\blocal-legacy\b/, label: 'local-legacy skills pack' },
    { re: /\bxtrm-tools@/, label: 'plugin-era xtrm-tools@ reference' },
    { re: /plugins\/cache\/xtrm/, label: 'Claude plugin cache path' },
    { re: /"[^"]*\/tmp\/claude-[^"]*"/, label: 'ephemeral /tmp/claude- path' },
    { re: /\.xtrm\/worktrees\//, label: 'worktree-local path (does not survive the worktree)' },
    { re: /\/dev\/[^"]*\/cli\/dist\//, label: 'inline dev-checkout cli/dist path' },
    { re: /\.pi\/skills\/xtrm\b/, label: 'retired .pi/skills/xtrm view' },
];

// Keys xt itself wrote and no longer reads. Nothing is added here on suspicion
// — each entry must have a matching removal in the installer.
const RETIRED_PI_KEYS: Array<{ key: string; since: string }> = [
    { key: 'xtrmExternalCompact', since: 'removed by updatePiSettings (cli/src/core/pi-runtime.ts)' },
];

const SCRIPT_TOKEN_RE = /[^\s"';|&]*\.(?:sh|mjs|cjs|js|py|ts)\b/g;

interface CommandHookLike { command?: string }
interface WrapperLike extends HookWrapperLike { hooks?: CommandHookLike[] }
type HooksMap = Record<string, WrapperLike[]>;

async function readJsonOrNull(file: string): Promise<Record<string, unknown> | null> {
    try {
        return await fs.readJson(file) as Record<string, unknown>;
    } catch {
        return null;
    }
}

function expandHome(p: string, home: string): string {
    return p.startsWith('~/') ? path.join(home, p.slice(2)) : p;
}

/** Absolute script paths a hook command invokes. Relative tokens are skipped —
 *  their base directory depends on how the runtime spawns the hook. */
function scriptPathsIn(command: string, home: string): string[] {
    const out: string[] = [];
    for (const match of command.match(SCRIPT_TOKEN_RE) ?? []) {
        const token = expandHome(match.replace(/^["']|["']$/g, ''), home);
        if (path.isAbsolute(token)) out.push(token);
    }
    return out;
}

function registrationLabel(event: string, matcher: string, command: string): string {
    const shown = command.length > 90 ? `${command.slice(0, 87)}…` : command;
    return matcher ? `${event}[${matcher}] ${shown}` : `${event} ${shown}`;
}

/** Which installer owns a hook command, inferred from the path it invokes.
 *  Used only to address the remediation at the right installer. */
function ownerOf(command: string): 'xtrm' | 'xtmux' | 'unknown' {
    if (/[/.]xtrm\/hooks\//.test(command)) return 'xtrm';
    if (/\/hooks\/xtmux\//.test(command)) return 'xtmux';
    return 'unknown';
}

function remediationFor(owner: ReturnType<typeof ownerOf>): string {
    if (owner === 'xtrm') return 'xt update --apply';
    if (owner === 'xtmux') return 'owned by the xtmux installer — see xtrm-xus17; do not hand-edit';
    return 'owned by a third-party installer — re-run it, or remove the extra copies by hand';
}

async function auditHooksMap(
    hooks: HooksMap,
    file: string,
    scope: Scope,
    home: string,
    planned: SettingsFinding[],
): Promise<void> {
    // Tally by (event, matcher, command). The tuple is carried in the value so
    // a command containing spaces still reports its own event and matcher.
    const seen = new Map<string, { event: string; matcher: string; command: string; count: number }>();

    for (const [event, wrappers] of Object.entries(hooks)) {
        if (!Array.isArray(wrappers)) continue;
        for (const wrapper of wrappers) {
            const matcher = wrapper?.matcher ?? '';
            for (const hook of wrapper?.hooks ?? []) {
                const command = hook?.command ?? '';
                if (!command) continue;
                const key = `${event}�${matcher}�${command}`;
                const tally = seen.get(key);
                if (tally) tally.count += 1;
                else seen.set(key, { event, matcher, command, count: 1 });

                for (const script of scriptPathsIn(command, home)) {
                    if (await fs.pathExists(script)) continue;
                    planned.push({
                        kind: 'dead-hook-command',
                        scope,
                        file,
                        subject: registrationLabel(event, matcher, command),
                        evidence: `${script} does not exist`,
                        remediation: remediationFor(ownerOf(command)),
                    });
                }

                // Legacy Beads machinery (ADR section 41): a registration
                // invoking a beads-* hook file is actionable as
                // `legacy migration required`, never silently tolerated.
                // Hook findings are never fixable here — removal belongs to
                // `xt update --apply`, whose hook successors are owned by
                // xtrm-6qu.6 (SEAM).
                const beadsHook = command.match(/beads-[A-Za-z0-9_-]*\.m?[jt]s/);
                if (beadsHook) {
                    planned.push({
                        kind: 'legacy-beads-hook',
                        scope,
                        file,
                        subject: registrationLabel(event, matcher, command),
                        evidence: `references legacy Beads hook ${beadsHook[0]}`,
                        remediation: 'xt update --apply (Substrate migration retires legacy Beads hooks)',
                    });
                }
            }
        }
    }

    for (const { event, matcher, command, count } of seen.values()) {
        if (count < 2) continue;
        planned.push({
            kind: 'duplicate-registration',
            scope,
            file,
            subject: registrationLabel(event, matcher, command),
            evidence: `registered ${count}× in this file — the hook fires ${count} times per ${event}`,
            remediation: remediationFor(ownerOf(command)),
        });
    }
}

function auditLegacyPatterns(raw: string, file: string, scope: Scope, planned: SettingsFinding[]): void {
    for (const { re, label } of LEGACY_PATTERNS) {
        const match = re.exec(raw);
        if (!match) continue;
        planned.push({
            kind: 'legacy-path',
            scope,
            file,
            subject: label,
            evidence: match[0].length > 120 ? `${match[0].slice(0, 117)}…` : match[0],
            remediation: 'xt update --apply (re-renders the xtrm-managed block)',
        });
    }
}

async function auditClaudeSettings(
    file: string,
    scope: Scope,
    home: string,
    outcome: SettingsAuditOutcome,
    projectRoot?: string,
): Promise<void> {
    if (!await fs.pathExists(file)) return;
    outcome.scanned.push(file);

    let raw: string;
    let settings: Record<string, unknown> | null;
    try {
        raw = await fs.readFile(file, 'utf8');
        settings = JSON.parse(raw) as Record<string, unknown>;
    } catch (error) {
        outcome.failed.push({ file, error: error instanceof Error ? error.message : String(error) });
        return;
    }

    const hooks = (settings.hooks ?? {}) as HooksMap;
    await auditHooksMap(hooks, file, scope, home, outcome.planned);
    auditLegacyPatterns(raw, file, scope, outcome.planned);

    if (scope !== 'project' || !projectRoot) return;

    // Ownership proof for project entries the global block already covers.
    const plan = await planLegacyHookDedupe(projectRoot, hooks, { home });
    if (plan.skipped) {
        outcome.failed.push({ file, error: `duplicate-of-global check skipped: ${plan.skipped}` });
        return;
    }
    for (const item of plan.planned) {
        outcome.planned.push({
            kind: 'duplicate-of-global',
            scope,
            file,
            subject: registrationLabel(item.event, item.matcher, item.command),
            evidence: 'the global block registers the same (event, matcher, command) against a byte-identical hook file',
            remediation: 'xt update --apply (phase 6 prunes it), or scripts/dedupe-legacy-hooks.mjs --apply for a fleet sweep',
        });
    }
    for (const item of plan.preserved) {
        outcome.preserved.push({
            scope,
            file,
            subject: registrationLabel(item.event, item.matcher, item.command),
            classification: item.classification,
            reason: item.reason,
        });
    }
}

function stringArray(value: unknown): string[] {
    return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === 'string') : [];
}

async function auditPiSettings(
    file: string,
    scope: Scope,
    home: string,
    outcome: SettingsAuditOutcome,
    globalPiEntries?: Set<string>,
): Promise<void> {
    if (!await fs.pathExists(file)) return;
    outcome.scanned.push(file);

    let raw: string;
    let settings: Record<string, unknown> | null;
    try {
        raw = await fs.readFile(file, 'utf8');
        settings = JSON.parse(raw) as Record<string, unknown>;
    } catch (error) {
        outcome.failed.push({ file, error: error instanceof Error ? error.message : String(error) });
        return;
    }

    auditLegacyPatterns(raw, file, scope, outcome.planned);

    for (const { key, since } of RETIRED_PI_KEYS) {
        if (!(key in settings)) continue;
        outcome.planned.push({
            kind: 'orphaned-key',
            scope,
            file,
            subject: key,
            evidence: `no reader consumes this key — ${since}`,
            remediation: 'xt update --apply, or xt doctor settings --fix --apply',
            fix: { op: 'delete-key', key },
        });
    }

    // Path-valued entries that point nowhere. npm: package ids are left alone —
    // resolving them means hitting the registry, which an audit must not do.
    const base = path.dirname(file);
    for (const field of ['skills', 'extensions'] as const) {
        for (const entry of stringArray(settings[field])) {
            if (!/^[.~/]/.test(entry)) continue;
            const resolved = path.resolve(base, expandHome(entry, home));
            if (await fs.pathExists(resolved)) continue;
            // Only xt's own retired pointers are removable. A dangling path the
            // operator wrote is reported and left alone — the directory may
            // simply not exist yet on this machine.
            const owned = LEGACY_XTRM_SKILLS_ENTRIES.has(entry);
            outcome.planned.push({
                kind: 'dangling-reference',
                scope,
                file,
                subject: `${field}[] → ${entry}`,
                evidence: owned
                    ? `${resolved} does not exist — retired xtrm skills pointer`
                    : `${resolved} does not exist`,
                remediation: owned
                    ? 'xt doctor settings --fix --apply'
                    : 'not xt-owned — repair or remove the entry by hand',
                ...(owned ? { fix: { op: 'remove-array-entry' as const, field, entry } } : {}),
            });
        }
    }

    if (scope !== 'project' || !globalPiEntries) return;

    for (const field of PI_ARRAY_FIELDS) {
        for (const entry of stringArray(settings[field])) {
            if (!globalPiEntries.has(`${field}�${entry}`)) continue;
            outcome.planned.push({
                kind: 'duplicate-of-global',
                scope,
                file,
                subject: `${field}[] → ${entry}`,
                // Not a harmless duplicate: Pi's getPackageIdentity ignores scope
                // for npm sources, so dedupePackages collides the two entries and
                // the PROJECT one wins — shadowing the global install with
                // whatever copy sits under <project>/.pi/npm (xtrm-tzzud.1).
                evidence: 'the global Pi settings already declare this entry — the project copy shadows it',
                remediation: 'xt update --apply, or xt doctor settings --fix --apply',
                fix: { op: 'remove-array-entry', field, entry },
            });
        }
    }
}

async function backupFile(file: string, stamp: string, home: string): Promise<string> {
    const backupDir = path.join(home, '.xtrm', 'migration-backups');
    await fs.ensureDir(backupDir);
    const name = `${path.basename(path.dirname(file))}-${path.basename(file, '.json')}-${stamp}.json`;
    const backup = path.join(backupDir, name);
    await fs.copy(file, backup);
    return backup;
}

function applyFixesToSettings(
    settings: Record<string, unknown>,
    fixes: readonly FixAction[],
): Record<string, unknown> {
    const next = { ...settings };
    for (const fix of fixes) {
        if (fix.op === 'delete-key') {
            delete next[fix.key];
            continue;
        }
        next[fix.field] = stringArray(next[fix.field]).filter((entry) => entry !== fix.entry);
    }
    return next;
}

/**
 * Remove every finding the audit marked with a `fix`. Dry-run unless `apply`
 * is set; each mutated file is copied into ~/.xtrm/migration-backups before
 * the write, the same contract as scripts/dedupe-legacy-hooks.mjs.
 *
 * Each file is re-read immediately before writing. The audit that produced
 * these findings may be seconds old, and a settings.json that changed
 * underneath us must not be clobbered from a stale in-memory copy.
 */
export async function applySettingsFixes(
    outcome: SettingsAuditOutcome,
    opts: { apply?: boolean; stamp?: string; home?: string } = {},
): Promise<SettingsAuditOutcome> {
    const fixable = outcome.planned.filter(
        (finding): finding is SettingsFinding & { fix: FixAction } => Boolean(finding.fix),
    );
    if (fixable.length === 0 || !opts.apply) return outcome;

    const home = opts.home ?? os.homedir();
    const stamp = opts.stamp ?? new Date().toISOString().replace(/[:.]/g, '-');
    const byFile = new Map<string, Array<SettingsFinding & { fix: FixAction }>>();
    for (const finding of fixable) {
        byFile.set(finding.file, [...(byFile.get(finding.file) ?? []), finding]);
    }

    for (const [file, findings] of byFile) {
        try {
            const settings = await readJsonOrNull(file);
            if (!settings) {
                outcome.failed.push({ file, error: 'settings.json vanished or became unparseable before apply' });
                continue;
            }
            const next = applyFixesToSettings(settings, findings.map((finding) => finding.fix));
            if (JSON.stringify(next) === JSON.stringify(settings)) continue;

            const backup = await backupFile(file, stamp, home);
            await fs.writeFile(file, `${JSON.stringify(next, null, 2)}\n`);
            outcome.changed = true;
            for (const finding of findings) outcome.applied.push({ file, subject: finding.subject, backup });
        } catch (error) {
            outcome.failed.push({ file, error: error instanceof Error ? error.message : String(error) });
        }
    }

    return outcome;
}

function globalPiSettingsPaths(home: string): string[] {
    const agentDir = process.env.PI_AGENT_DIR ?? path.join(home, '.pi', 'agent');
    return [path.join(agentDir, 'settings.json'), path.join(home, '.pi', 'settings.json')];
}

async function collectGlobalPiEntries(home: string): Promise<Set<string>> {
    const entries = new Set<string>();
    for (const file of globalPiSettingsPaths(home)) {
        const settings = await readJsonOrNull(file);
        if (!settings) continue;
        for (const field of ['packages', 'extensions', 'skills'] as const) {
            for (const entry of stringArray(settings[field])) entries.add(`${field}�${entry}`);
        }
    }
    return entries;
}

const CONSUMER_MARKERS = [path.join('.xtrm', 'registry.json'), path.join('.xtrm', 'hooks'), path.join('.xtrm', 'config')];

/** Same discovery rule as scripts/dedupe-legacy-hooks.mjs: one level under
 *  ~/dev and ~/projects, a directory carrying any xt consumer marker. */
export async function discoverConsumerProjects(home: string): Promise<string[]> {
    const found: string[] = [];
    for (const root of [path.join(home, 'dev'), path.join(home, 'projects')]) {
        const entries = await fs.readdir(root, { withFileTypes: true }).catch(() => []);
        for (const entry of entries) {
            if (!entry.isDirectory()) continue;
            const dir = path.join(root, entry.name);
            for (const marker of CONSUMER_MARKERS) {
                if (await fs.pathExists(path.join(dir, marker))) { found.push(dir); break; }
            }
        }
    }
    return found.sort((a, b) => a.localeCompare(b));
}

export async function auditSettings(opts: AuditOptions): Promise<SettingsAuditOutcome> {
    const home = opts.home ?? os.homedir();
    const outcome: SettingsAuditOutcome = {
        schema: 'ReconciliationOutcome/1',
        generatedAt: new Date().toISOString(),
        changed: false,
        planned: [],
        applied: [],
        preserved: [],
        failed: [],
        scanned: [],
    };

    if (opts.scope === 'home' || opts.scope === 'all') {
        await auditClaudeSettings(path.join(home, '.claude', 'settings.json'), 'home', home, outcome);
        for (const file of globalPiSettingsPaths(home)) {
            await auditPiSettings(file, 'home', home, outcome);
        }
    }

    if (opts.scope === 'project' || opts.scope === 'all') {
        const roots = opts.scanAllRepos
            ? await discoverConsumerProjects(home)
            : (opts.projectRoot ? [opts.projectRoot] : []);
        const globalPiEntries = await collectGlobalPiEntries(home);
        for (const root of roots) {
            await auditClaudeSettings(path.join(root, '.claude', 'settings.json'), 'project', home, outcome, root);
            await auditPiSettings(path.join(root, '.pi', 'settings.json'), 'project', home, outcome, globalPiEntries);
        }
    }

    return outcome;
}
